"""Order totals composed from pricing and tax."""

from shop.pricing import bulk_discount, line_total
from shop.tax import tax_rate


def order_total(price: float, quantity: int, region: str) -> float:
    subtotal = line_total(price, quantity)
    discount = subtotal * bulk_discount(quantity)
    return round((subtotal - discount) * (1 + tax_rate(region)), 2)
